let session=null;const message=document.querySelector('#dashboard-status'),login=document.querySelector('#login-form'),dashboard=document.querySelector('#dashboard');
function signOut(){session=null;dashboard.hidden=true;login.hidden=false;document.querySelector('#bookings').replaceChildren();document.querySelector('#password').value='';message.textContent='Signed out.';}
if(!ready){message.textContent='The booking backend has not been connected yet.';login.querySelector('button').disabled=true;}
login.addEventListener('submit',async event=>{event.preventDefault();const button=login.querySelector('button');button.disabled=true;message.textContent='Signing in…';try{const auth=await api('/auth/v1/token?grant_type=password',{method:'POST',body:JSON.stringify({email:document.querySelector('#email').value.trim(),password:document.querySelector('#password').value})});const owners=await api('/rest/v1/studio_owners?select=user_id',{},auth.access_token);if(!owners.length)throw new Error('This account does not have studio access.');session={token:auth.access_token,expires:Date.now()+auth.expires_in*1000};document.querySelector('#password').value='';login.hidden=true;dashboard.hidden=false;await loadBookings();}catch(error){session=null;message.textContent=error.message;}finally{button.disabled=false;}});
async function loadBookings(){if(!session)return;if(Date.now()>=session.expires){signOut();message.textContent='Session expired. Please sign in again.';return;}message.textContent='Loading bookings…';try{const upcoming=document.querySelector('#booking-filter').value==='upcoming';const query=upcoming?`&preferred_at=gte.${encodeURIComponent(new Date().toISOString())}&status=in.(pending,confirmed)&order=preferred_at.asc`:'&order=preferred_at.desc';const rows=await api('/rest/v1/bookings?select=*&limit=200'+query,{},session.token);const visible=rows.filter(row=>document.querySelector('#booking-filter').value==='all'||(new Date(row.preferred_at)>=new Date()&&['pending','confirmed'].includes(row.status)));const root=document.querySelector('#bookings');root.replaceChildren();for(const row of visible){const card=document.createElement('article');card.className='booking-card';const title=document.createElement('h3');title.textContent=row.customer_name;const details=document.createElement('p');details.textContent=`${row.service_name} · ${row.base_price===null?'Price on consultation':'₦'+row.base_price.toLocaleString()} · ${new Intl.DateTimeFormat('en-NG',{dateStyle:'medium',timeStyle:'short',timeZone:'Africa/Lagos'}).format(new Date(row.preferred_at))} · ${row.status}`;const notes=document.createElement('p');notes.textContent=row.notes||'';const ref=document.createElement('small');ref.textContent=`Reference: ${row.id} · Contact: ${row.phone}`;const actions=document.createElement('div');actions.className='filters';const whatsapp=document.createElement('a');whatsapp.className='button';whatsapp.textContent='Continue on WhatsApp ↗';let digits=row.phone.replace(/\D/g,'');if(digits.startsWith('0'))digits='234'+digits.slice(1);whatsapp.href=`https://wa.me/${digits}?text=${encodeURIComponent(`Hi ${row.customer_name}, this is 23 Lux Nails about booking ${row.id}.`)}`;whatsapp.target='_blank';whatsapp.rel='noopener';actions.append(whatsapp);for(const status of ['confirmed','declined','completed','cancelled']){if(status===row.status)continue;const b=document.createElement('button');b.textContent=status==='confirmed'?'Confirm':status[0].toUpperCase()+status.slice(1);b.onclick=async()=>{b.disabled=true;try{await api(`/rest/v1/bookings?id=eq.${row.id}`,{method:'PATCH',body:JSON.stringify({status}),headers:{Prefer:'return=minimal'}},session.token);await loadBookings();}catch(error){message.textContent=error.message;b.disabled=false;}};actions.append(b);}card.append(title,details,notes,ref,actions);root.append(card);}message.textContent=`${visible.length} bookings shown (up to 200 matching appointments). Status changes do not send a customer message; use WhatsApp to notify them.`;}catch(error){message.textContent=error.message;}}
document.querySelector('#refresh').onclick=loadBookings;document.querySelector('#booking-filter').onchange=loadBookings;document.querySelector('#logout').onclick=async()=>{const token=session?.token;signOut();if(token)await api('/auth/v1/logout',{method:'POST'},token).catch(()=>{});};
